@dataclass(kw_only=True, slots=True)
class ArcCreate(_Model):
    """Input of `cad.arc.create` v1: one circular arc on a named layer, as the
    document stores it (centre, radius, and the angles it runs between counter-
    clockwise), written as one undo step. The arc tool computes the arc of each
    of its methods (three points; start, centre and end, angle or chord; start,
    end and centre, angle, direction or radius; centre first; continuing the
    last object) through the shared core and gives it here. Everything the
    command depends on is here (TODOS.md CMD-07): the tool fills `layerId`
    from the active layer and `color` from the current colour.

    Refusals (`CommandError.code`), checked in this order: `not_finite` (`c`,
    x before y, then `r`, `a0`, `a1`), `invalid_radius` (not above zero),
    `invalid_line_weight` (not from 0 to 100 mm), `invalid_revision`, `revision_conflict` (status `conflict`),
    `layer_not_found`, `not_a_layer`, `layer_locked`; on the desktop also
    `slots_exhausted`. Warning: `layer_hidden` (it is written all the same).
    The angles are stored as given: equal angles are a full turn, as the
    document reads them; no angle is refused for its size.
    Attributes:
        layer_id: The layer it goes on: a layer's id (`LayerNode.id`), not a group's.
        c: Its centre: x east (Y), y north (X), in the project's units (m), float64.
        r: Its radius, in the project's units; above zero.
        a0: Where it starts: radians, counter-clockwise from east (a geometry
            angle, not a surveying bearing).
        a1: Where it ends: the arc runs counter-clockwise from `a0` to `a1`.
        attrs: GIS attributes, text in v1. Absent: none.
        color: Colour override (`EntityBase.color`). Absent: the layer's colour (katmana göre).
        expected_revision: The document revision the input was prepared against, as decimal text
            (from a plan, or the document). When given and the document is no
            longer at it, nothing is written and the answer is `conflict`.
        line_weight: Its own line weight, paper mm (`EntityBase.line_weight`, 0 the
            thinnest, at most 100; docs/adr/0139): what the tools give a new
            object from the current weight. Absent: the layer's (katmana göre).
    """
    layer_id: str
    c: Vec2
    r: float
    a0: float
    a1: float
    attrs: dict[str, str] | None | Unset = UNSET
    color: str | None | Unset = UNSET
    expected_revision: str | None | Unset = UNSET
    line_weight: float | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["layerId"] = self.layer_id
        out["c"] = _vec2_out(self.c)
        out["r"] = float(self.r)
        out["a0"] = float(self.a0)
        out["a1"] = float(self.a1)
        if self.attrs is not UNSET:
            out["attrs"] = None if self.attrs is None else dict(self.attrs)
        if self.color is not UNSET:
            out["color"] = self.color
        if self.expected_revision is not UNSET:
            out["expectedRevision"] = self.expected_revision
        if self.line_weight is not UNSET:
            out["lineWeight"] = None if self.line_weight is None else float(self.line_weight)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> ArcCreate:
        return cls(
            layer_id=data["layerId"],
            c=Vec2.from_json(data["c"]),
            r=float(data["r"]),
            a0=float(data["a0"]),
            a1=float(data["a1"]),
            attrs=UNSET if "attrs" not in data else None if data["attrs"] is None else dict(data["attrs"]),
            color=data.get("color", UNSET),
            expected_revision=data.get("expectedRevision", UNSET),
            line_weight=UNSET if "lineWeight" not in data else None if data["lineWeight"] is None else float(data["lineWeight"]),
        )


